struct RestoreProgress {
    let percent: Int
}
func completed(_ item: RestoreProgress) -> RestoreProgress {
    RestoreProgress(percent: 100)
}
let original = RestoreProgress(percent: 10)
let result = completed(original)
print(original.percent, result.percent)

Передача ссылки разделяла один объект. Новый снимок значения оставляет исходный прогресс прежним.

