func compose<A, B, C>(
    _ first: @escaping (A) -> B,
    _ second: @escaping (B) -> C
) -> (A) -> C {
    { second(first($0)) }
}
func clamp(_ value: Int) -> Int { min(max(value, 0), 100) }
func label(_ value: Int) -> String { "\(value)%" }
let display = compose(clamp, label)
print(display(120))
print(display(-5))

Вывод: 100%, 0%. Порядок функций закреплён типами A → B → C; compose сама возвращает правило.
